export const GLOSSARY_SHARD = Object.freeze({"altcoin":{"slug":"altcoin","cat":"basics","en":"Altcoin","contentLocale":"ko","term":"알트코인(Altcoin)","aka":["알트","Altcoin"],"short":"알트코인은 비트코인을 제외한 나머지 암호화폐를 통틀어 부르는 말로, 이더리움, 솔라나, XRP 같은 대형 코인부터 소형 토큰까지 모두 포함합니다.","body":[["알트코인은 대안(alternative) 코인이라는 뜻에서 나온 말입니다. 처음에는 ",["비트코인","bitcoin"],"을 변형한 코인을 가리켰지만, 지금은 비트코인이 아닌 거의 모든 코인과 토큰을 부르는 표현으로 쓰입니다. ",["스테이블코인","stablecoin"],"은 성격이 달라 따로 구분하는 경우가 많습니다."],["알트코인은 ",["시가총액","market-capitalization"],", ",["유동성","liquidity"],", 프로젝트 성격이 천차만별입니다. 대형 알트코인은 ",["거래량","trading-volume"],"이 많아 호가가 촘촘하지만, 소형 알트코인은 적은 주문에도 가격이 크게 움직이고 상장 폐지 위험도 상대적으로 높습니다."],["알트코인 가격은 비트코인 흐름에 영향을 많이 받습니다. 비트코인이 크게 하락할 때 알트코인은 더 큰 폭으로 떨어지는 경우가 흔합니다. 같은 이름의 코인이라도 ",["거래소","centralized-exchange"],"마다 상장 여부와 지원 네트워크가 다르니 확인이 필요합니다."]],"example":"비트코인이 하루에 5% 하락한 날, 시가총액이 큰 알트코인 A는 7%, 거래량이 적은 소형 알트코인 B는 18% 하락했다고 가정해 보겠습니다. 각각 100만 원씩 들고 있었다면 A는 93만 원, B는 82만 원이 됩니다. 같은 시장 충격에도 알트코인의 규모와 유동성에 따라 손실 폭이 크게 달라진다는 점을 보여 주는 예입니다.","mistakes":["가격이 낮은 알트코인을 싸다고 판단하지만, 단가가 아니라 시가총액과 공급량을 봐야 합니다.","거래량이 적은 알트코인에 시장가 주문을 넣어 큰 슬리피지를 겪습니다.","SNS에서 이름만 들은 알트코인을 같은 티커의 다른 토큰과 혼동해 매수합니다."],"faq":[{"q":"이더리움도 알트코인인가요?","a":"넓은 의미로는 그렇습니다. 비트코인이 아닌 코인이므로 알트코인에 포함되지만, 규모가 커서 따로 구분해 부르기도 합니다."},{"q":"알트코인 시즌이란 무엇인가요?","a":"일정 기간 알트코인 다수가 비트코인보다 높은 상승률을 보이는 장세를 말합니다. 시점과 기준은 지표마다 달라 명확하게 정해진 정의는 없습니다."}],"title":"알트코인이란? 뜻과 비트코인과의 차이","description":"알트코인의 뜻과 범위, 대형·소형 알트코인의 차이, 비트코인 하락장에서 더 크게 흔들리는 이유를 예시로 설명합니다.","related":[["bitcoin","비트코인(Bitcoin, BTC)","비트코인(BTC)은 2009년 운영을 시작한 최초의 암호화폐로, 작업증명 블록체인 위에서 중앙 관리자 없이 발행되며 총발행량이 2,100만 개로 정해져 있습니다."],["memecoin","밈코인(Memecoin)","밈코인은 인터넷 밈이나 유머, 커뮤니티 문화를 바탕으로 만들어진 암호화폐로, 뚜렷한 기능보다 관심과 화제성이 가격을 크게 좌우하는 코인입니다."],["market-capitalization","시가총액(Market Cap)","시가총액은 코인의 현재 가격에 유통 공급량을 곱한 값으로, 시장이 그 자산 전체를 얼마로 평가하고 있는지 보여 주는 지표입니다."],["token-listing","토큰 상장(Token listing)","토큰 상장은 거래소가 심사를 거쳐 새로운 코인이나 토큰의 입금, 거래 페어, 출금을 열어 사용자가 사고팔 수 있게 하는 것입니다."],["volatility","변동성(Volatility)","변동성은 일정 기간 동안 가격이 얼마나 크고 빠르게 오르내리는지를 나타내는 정도로, 변동성이 클수록 같은 기간에 가격이 더 크게 움직입니다."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":"/coins","cta":false},"layer-2":{"slug":"layer-2","cat":"basics","en":"Layer 2 (L2)","contentLocale":"ko","term":"레이어2(Layer 2, L2)","aka":["L2","레이어 2","롤업"],"short":"레이어2(L2)는 레이어1 블록체인 위에서 거래를 더 빠르고 저렴하게 처리한 뒤, 그 결과를 레이어1에 기록해 보안을 이어받는 확장 네트워크입니다.","body":[[["이더리움","ethereum"]," ",["메인넷","layer-1"],"은 처리할 수 있는 거래 수가 한정돼 있어 혼잡할 때 ",["가스비","gas-fee"],"가 비싸집니다. 레이어2는 많은 거래를 묶어 따로 처리하고, 요약된 데이터나 증명만 이더리움에 올려 비용을 나눕니다. 이런 방식을 롤업이라고 부릅니다."],["롤업은 크게 옵티미스틱 롤업(Arbitrum, Optimism, Base 등)과 영지식 롤업(zkSync, Starknet 등)으로 나뉩니다. 옵티미스틱 롤업은 공식 ",["브리지","cross-chain-bridge"],"로 L1에 출금할 때 이의 제기 기간 때문에 보통 7일 정도가 걸립니다."],["L2에서도 가스비는 대개 ETH로 냅니다. ",["거래소","centralized-exchange"]," 출금 화면에서 Arbitrum One이나 Base 같은 네트워크를 고르면 수수료가 낮지만, 받는 지갑이나 서비스가 그 네트워크를 지원해야 합니다. ",["비트코인","bitcoin"],"에도 라이트닝 네트워크 같은 레이어2 솔루션이 있습니다."]],"example":"DEX에서 하루에 4번 토큰을 교환한다고 해 보겠습니다. 메인넷 가스비가 한 번에 5달러라면 하루 20달러, 한 달 30일이면 600달러입니다. 레이어2에서 한 번에 0.1달러라면 하루 0.4달러, 한 달 12달러입니다. 다만 L2 자산을 메인넷으로 옮길 때 공식 브리지를 쓰면 대기 시간이 생길 수 있어 이동 계획도 함께 세워야 합니다.","mistakes":["L2에서는 ETH가 필요 없다고 생각해 가스비용 ETH를 준비하지 않습니다.","거래소가 지원하지 않는 L2 네트워크로 입금해 자산이 바로 반영되지 않습니다.","옵티미스틱 롤업의 공식 브리지 출금이 즉시 처리된다고 오해합니다."],"faq":[{"q":"레이어2는 안전한가요?","a":"레이어2는 이더리움의 보안을 일부 이어받지만, 시퀀서 운영 방식, 업그레이드 권한, 브리지 구조에 따라 추가 위험이 있습니다. 프로젝트마다 탈중앙화 수준이 다릅니다."},{"q":"레이어2 토큰으로 가스비를 내나요?","a":"대부분의 이더리움 L2는 ETH로 가스비를 냅니다. ARB나 OP 같은 토큰은 주로 거버넌스용으로 쓰입니다."}],"title":"레이어2(L2)란? 뜻과 롤업 원리 정리","description":"레이어2(L2)의 뜻과 롤업 원리, Arbitrum·Optimism·Base 등 대표 네트워크, 가스비 절감과 브리지 출금 주의점을 설명합니다.","related":[["layer-1","레이어1(Layer 1, L1)","레이어1(L1)은 거래의 처리와 최종 확정을 스스로 담당하는 기본 블록체인으로, 비트코인, 이더리움, 솔라나처럼 자체 합의 방식과 네이티브 코인을 가집니다."],["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."],["cross-chain-bridge","크로스체인 브리지(Cross-chain Bridge)","크로스체인 브리지는 한 블록체인의 자산을 다른 블록체인에서 쓸 수 있도록 옮겨 주는 서비스로, 보통 원래 체인에 자산을 잠그고 다른 체인에서 같은 양을 발행합니다."],["ethereum","이더리움(Ethereum, ETH)","이더리움(ETH)은 스마트 컨트랙트를 실행할 수 있는 블록체인 플랫폼이며, ETH는 그 네트워크에서 가스비를 내고 스테이킹에 쓰이는 기본 코인입니다."],["blockchain-network","입금 네트워크(체인 선택)","입금 네트워크는 같은 코인을 어떤 블록체인으로 보낼지 고르는 설정으로, 보내는 쪽과 받는 쪽의 네트워크가 반드시 같아야 합니다."]],"lesson":null,"coin":{"slug":"arbitrum","name":"Arbitrum","symbol":"ARB"},"tool":null,"cta":false},"spot-trading":{"slug":"spot-trading","cat":"trading","en":"Spot trading","contentLocale":"ko","term":"현물 거래(Spot Trading)","aka":["현물","스팟","Spot"],"short":"현물 거래는 코인을 현재 가격에 실제로 사고팔아 즉시 소유권이 넘어가는 거래 방식으로, 산 코인은 바로 내 계정 잔고에 들어옵니다.","body":[["현물 거래에서 BTC를 사면 실제 BTC를 보유하게 되며, 원하면 ",["개인 지갑","non-custodial-wallet"],"으로 출금할 수도 있습니다. 선물처럼 만기나 ",["펀딩비","funding-rate"],"가 없고, ",["레버리지","leverage"],"를 쓰지 않는 한 가격이 크게 떨어져도 ",["강제청산","liquidation"],"되지 않습니다."],["현물에서 수익은 가격이 오를 때만 생깁니다. 가격 하락에 베팅하려면 선물 숏이나 ",["마진 거래","margin-trading"],"가 필요합니다. 그래서 현물은 초보자에게 가장 기본적인 거래 방식이고, ",["장기 보유","hodl"],"나 적립식 매수에도 주로 쓰입니다."],"현물 거래 비용은 거래 수수료, 매수·매도 호가 차이(스프레드), 슬리피지로 구성됩니다. 지정가 주문은 메이커 수수료, 시장가 주문은 테이커 수수료가 적용되는 경우가 많고, 거래소와 등급에 따라 수수료율이 다릅니다."],"example":"ETH 가격이 2,000 USDT일 때 현물로 400 USDT어치, 즉 0.2 ETH를 샀다고 가정해 보겠습니다. 가격이 1,500 USDT로 25% 떨어지면 평가금액은 300 USDT가 되지만 0.2 ETH는 그대로 남아 있습니다. 같은 금액을 5배 레버리지 선물 롱으로 잡았다면 20% 정도 하락에서 증거금을 거의 다 잃고 청산될 수 있었습니다. 현물과 선물의 위험 구조가 다른 이유입니다.","mistakes":["현물 마켓과 선물 마켓 화면을 헷갈려 의도치 않게 레버리지 포지션을 엽니다.","거래 수수료만 보고 스프레드와 슬리피지 비용을 무시합니다.","현물은 위험이 없다고 생각해 한 종목에 자금을 몰아넣습니다."],"faq":[{"q":"현물 거래와 선물 거래의 차이는 무엇인가요?","a":"현물은 코인을 실제로 사고파는 것이고, 선물은 코인 가격에 연동된 계약을 거래하는 것입니다. 선물은 레버리지와 숏이 가능하지만 청산과 펀딩비 같은 추가 위험이 있습니다."},{"q":"현물로 산 코인은 청산되나요?","a":"레버리지를 쓰지 않은 현물 보유분은 청산되지 않습니다. 가격이 떨어지면 평가금액이 줄어들 뿐 코인 수량은 그대로입니다."}],"title":"현물 거래란? 뜻과 선물 거래와의 차이","description":"코인 현물 거래의 뜻과 특징, 선물과의 위험 구조 차이, 수수료·스프레드·슬리피지 등 현물 거래 비용을 예시로 설명합니다.","related":[["trading-pair","거래 페어(Trading Pair)","거래 페어는 어떤 코인을 어떤 자산으로 사고파는지를 나타내는 조합으로, BTC/USDT는 BTC를 USDT로 거래한다는 뜻입니다."],["market-order","시장가 주문(Market Order)","시장가 주문은 가격을 지정하지 않고 현재 호가창에 있는 가장 유리한 가격부터 즉시 체결하는 주문으로, 빠른 체결을 대가로 가격을 보장받지 못합니다."],["limit-order","지정가 주문(Limit Order)","지정가 주문은 사거나 팔 가격을 직접 정해 두고, 시장 가격이 그 가격이나 더 유리한 가격에 도달했을 때만 체결되는 주문입니다."],["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"첫 현물 거래: 100에서 0.002 BTC까지"},"coin":null,"tool":"/compare","cta":true},"candlestick-chart":{"slug":"candlestick-chart","cat":"trading","en":"Candlestick chart","contentLocale":"ko","term":"캔들차트(Candlestick Chart)","aka":["봉차트","캔들","candlestick"],"short":"캔들차트는 정해진 시간 동안의 시가, 고가, 저가, 종가를 막대 하나로 표시해 가격 움직임을 한눈에 보여 주는 차트입니다.","body":["캔들 하나는 몸통과 꼬리로 이루어집니다. 몸통은 시가와 종가 사이를, 위아래 꼬리는 그 시간 동안의 고가와 저가를 나타냅니다. 1분봉, 1시간봉, 일봉처럼 캔들 하나가 담는 시간을 바꿔 볼 수 있습니다.",["한국 ",["거래소","centralized-exchange"]," 앱에서는 보통 상승 캔들(양봉)을 빨간색, 하락 캔들(음봉)을 파란색으로 표시합니다. 해외 거래소는 상승을 초록색, 하락을 빨간색으로 쓰는 경우가 많아 설정을 확인해야 헷갈리지 않습니다."],["긴 아래꼬리는 저가에서 매수세가 들어와 가격을 끌어올렸다는 뜻으로, 긴 위꼬리는 고가에서 매도 압력이 컸다는 뜻으로 해석하는 경우가 많습니다. 캔들 모양은 ",["거래량","trading-volume"],", ",["지지선","support-and-resistance"],"과 함께 볼 때 의미가 커집니다."]],"example":[["BTC","bitcoin"]," 1시간봉 하나가 시가 60,000 ",["USDT","usdt"],", 고가 60,900 USDT, 저가 59,400 USDT, 종가 60,600 USDT라고 가정해 보겠습니다. 종가가 시가보다 높으니 양봉이고, 몸통 길이는 600 USDT입니다. 위꼬리는 60,900 − 60,600 = 300 USDT, 아래꼬리는 60,000 − 59,400 = 600 USDT입니다. 아래꼬리가 몸통만큼 길다는 것은 한때 크게 밀렸다가 매수세로 회복했다는 뜻입니다."],"mistakes":["해외 거래소의 색상 규칙을 모르고 빨간 캔들을 상승으로 착각합니다.","아직 마감되지 않은 현재 캔들의 모양만 보고 성급하게 판단합니다.","1분봉처럼 짧은 시간 단위의 패턴을 장기 추세처럼 해석합니다."],"faq":[{"q":"양봉과 음봉의 차이는 무엇인가요?","a":"종가가 시가보다 높으면 양봉, 낮으면 음봉입니다. 색상은 거래소와 설정에 따라 다르므로 시가와 종가 위치로 판단하는 것이 정확합니다."},{"q":"꼬리가 긴 캔들은 무엇을 뜻하나요?","a":"그 시간 동안 가격이 크게 움직였다가 되돌아왔다는 뜻입니다. 아래꼬리는 저가 매수세, 위꼬리는 고가 매도세로 보는 경우가 많지만 단독 신호로 쓰기에는 부족합니다."}],"title":"캔들차트란? 양봉·음봉과 꼬리 읽는 법","description":"캔들차트의 시가·고가·저가·종가 구조, 양봉과 음봉의 차이, 꼬리가 뜻하는 매수·매도세를 예시로 설명합니다.","related":[["support-and-resistance","지지선과 저항선(Support and Resistance)","지지선은 매수세가 몰려 가격 하락이 자주 멈추는 가격대이고, 저항선은 매도세가 몰려 가격 상승이 자주 막히는 가격대입니다."],["volatility","변동성(Volatility)","변동성은 일정 기간 동안 가격이 얼마나 크고 빠르게 오르내리는지를 나타내는 정도로, 변동성이 클수록 같은 기간에 가격이 더 크게 움직입니다."],["trading-volume","거래량(Trading Volume)","거래량은 일정 기간 동안 실제로 체결된 코인의 수량 또는 금액을 말하며, 보통 24시간 기준으로 시장의 관심과 활발함을 보여 줍니다."],["all-time-high","역대 최고가(ATH)","역대 최고가(ATH)는 어떤 자산이 거래를 시작한 이후 기록한 가장 높은 가격으로, 코인 커뮤니티에서는 전고점이나 신고가라는 표현도 함께 씁니다."]],"lesson":{"id":"E15","slug":"read-a-candlestick","ep":15,"title":"캔들 하나: 알려주는 네 가지 정보는 무엇인가?"},"coin":null,"tool":null,"cta":false},"last-price":{"slug":"last-price","cat":"derivatives","en":"Last traded price","contentLocale":"ko","term":"최근 체결가(Last Price)","aka":["현재가","최종 체결가","last price","시장가격"],"short":"최근 체결가는 해당 거래소 시장에서 가장 마지막으로 실제 체결된 거래의 가격으로, 차트와 시세 화면에 현재가로 표시되는 값입니다.","body":[[["호가창","order-book"],"에서 매수 주문과 매도 주문이 만나 거래가 성사될 때마다 최근 체결가가 갱신됩니다. ",["거래소","centralized-exchange"]," 앱의 큰 숫자와 ",["캔들차트","candlestick-chart"],"는 대부분 이 가격을 보여 줍니다."],["최근 체결가는 실제 거래 결과이므로 그 순간 호가 상황에 크게 영향을 받습니다. ",["유동성","liquidity"],"이 얇거나 큰 ",["시장가 주문","market-order"],"이 들어오면 짧은 시간 크게 튀었다가 돌아오기도 합니다."],["선물 거래에서는 손절이나 익절 같은 조건부 주문의 발동 기준을 최근 체결가로 할지 ",["마크 가격","mark-price"],"으로 할지 고를 수 있는 거래소가 많습니다. 최근 체결가 기준은 반응이 빠르지만 순간적인 꼬리에 발동되기 쉽고, 마크 가격 기준은 더 안정적이지만 반응이 조금 늦습니다."]],"example":"BTC 무기한 선물의 최근 체결가가 61,000 USDT이고, 61,500 USDT에 숏 포지션의 손절을 걸어 두었다고 가정해 보겠습니다. 큰 매수 주문으로 체결가가 몇 초 동안 61,550 USDT까지 튀었다가 61,100 USDT로 돌아왔고, 마크 가격은 61,200 USDT를 넘지 않았습니다. 손절 기준을 최근 체결가로 했다면 손절이 발동했겠지만, 마크 가격으로 했다면 포지션은 유지됩니다.","mistakes":["차트의 현재가를 마크 가격이나 지수 가격과 같은 것으로 생각합니다.","조건부 주문의 발동 기준 가격 설정을 확인하지 않아 순간적인 꼬리에 손절됩니다.","거래소마다 최근 체결가가 다를 수 있다는 것을 모르고 다른 거래소 시세로 판단합니다."],"faq":[{"q":"최근 체결가와 마크 가격 중 무엇으로 손절을 걸어야 하나요?","a":"순간적인 꼬리에 털리는 것을 줄이려면 마크 가격, 빠른 반응이 중요하면 최근 체결가를 선택합니다. 정답은 없으며 매매 방식에 맞게 고르면 됩니다."},{"q":"주문하면 최근 체결가에 사지나요?","a":"시장가 주문은 그 순간 호가창의 가격으로 체결되므로 최근 체결가와 다를 수 있습니다. 이 차이가 슬리피지입니다."}],"title":"최근 체결가란? 마크 가격과 무엇이 다를까","description":"최근 체결가(현재가)의 뜻, 마크 가격·지수 가격과의 차이, 손절 주문 발동 기준을 고르는 방법을 설명합니다.","related":[["mark-price","마크 가격(Mark Price)","마크 가격은 선물 거래소가 평가 손익과 강제청산을 계산할 때 쓰는 기준 가격으로, 여러 현물 거래소의 지수 가격을 바탕으로 만들어 순간적인 가격 조작의 영향을 줄입니다."],["index-price","지수 가격(Index Price)","지수 가격은 여러 주요 현물 거래소의 가격을 가중 평균해 만든 기준 가격으로, 선물의 마크 가격과 펀딩비를 계산하는 바탕이 됩니다."],["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."],["stop-loss","손절 주문(Stop-Loss)","손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"화면에 보이는 가격이 왜 내 실제 체결 가격이 아닐까요?"},"coin":null,"tool":null,"cta":false},"funding-rate-arbitrage":{"slug":"funding-rate-arbitrage","cat":"derivatives","en":"Funding rate arbitrage","contentLocale":"ko","term":"펀딩비 차익거래(Funding Rate Arbitrage)","aka":["펀딩비 아비트라지","펀딩비 차익","funding rate arbitrage","펀비 차익거래"],"short":"펀딩비 차익거래는 현물을 사고 같은 양의 무기한 선물을 숏으로 잡아 가격 방향 위험을 상쇄한 채, 숏 포지션이 받는 펀딩비를 수익으로 얻는 전략입니다.","body":[[["펀딩비","funding-rate"],"가 플러스이면 숏이 롱으로부터 펀딩비를 받습니다. 현물 롱과 선물 숏을 같은 수량으로 들면 가격이 오르든 내리든 두 포지션의 손익이 상쇄되고, 펀딩비만 남습니다. 펀딩비가 마이너스로 바뀌면 오히려 비용을 내야 합니다."],"펀딩비는 시장 상황에 따라 계속 바뀌므로 수익은 확정되지 않습니다. 진입·청산 수수료 네 번, 현물과 선물의 가격 차이, 선물 증거금으로 묶이는 자금을 모두 계산해야 실제 수익률이 나옵니다.",["숨은 위험도 있습니다. 급등 시 선물 숏의 증거금이 부족하면 숏만 청산되어 ",["헤지","hedging"],"가 깨지고, 현물과 선물이 다른 ",["거래소","centralized-exchange"],"에 있으면 거래소 리스크와 자금 이동 지연도 떠안습니다. ",["통합 계정","unified-trading-account"],"에서 현물을 증거금으로 쓸 수 있는지도 거래소마다 다릅니다."]],"example":["ETH가 3,000 USDT일 때 현물 5 ETH를 사고 ",["무기한 선물","perpetual-futures"]," 5 ETH를 숏으로 잡았다고 가정해 보겠습니다. 포지션 규모는 15,000 USDT이고 펀딩비가 8시간마다 평균 +0.015%라면 한 번에 2.25 ",["USDT","usdt"],", 하루 6.75 USDT, 30일이면 202.5 USDT를 받습니다. 진입과 청산 수수료가 각각 0.1%씩 네 번이면 약 60 USDT이므로, 펀딩비가 유지된다는 가정에서 30일 순수익은 약 142.5 USDT입니다."],"mistakes":["한 번 본 높은 펀딩비가 계속 유지될 것이라 가정하고 연 수익률을 계산합니다.","선물 숏의 레버리지를 높여 증거금을 아끼다가 급등에 숏만 청산됩니다.","현물과 선물 수량을 정확히 맞추지 않아 방향 위험이 남습니다."],"faq":[{"q":"펀딩비 차익거래는 무위험인가요?","a":"가격 방향 위험은 줄지만 펀딩비 반전, 선물 청산, 거래소 리스크, 수수료 같은 위험과 비용은 남습니다. 무위험 수익으로 보면 안 됩니다."},{"q":"펀딩비가 마이너스이면 어떻게 하나요?","a":"현물 롱과 선물 숏 구조에서는 펀딩비를 내야 하므로 수익이 줄거나 손실이 납니다. 마이너스가 이어지면 포지션을 정리하는 기준을 미리 정해 두는 것이 좋습니다."}],"title":"펀딩비 차익거래란? 원리와 수익 계산","description":"펀딩비 차익거래의 원리, 현물 롱과 선물 숏으로 펀딩비를 받는 구조, 수수료와 청산 위험을 포함한 계산법을 설명합니다.","related":[["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."],["arbitrage","차익거래(Arbitrage)","차익거래는 같은 자산이 거래소나 시장에 따라 다른 가격에 거래될 때 싼 곳에서 사고 비싼 곳에서 팔아 가격 차이만큼 수익을 얻는 거래입니다."],["hedging","헤지(Hedging)","헤지는 이미 가진 포지션의 가격 변동 위험을 줄이기 위해 반대 방향으로 움직이는 포지션을 함께 잡는 위험 관리 방법입니다."],["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"가격은 그대로인데 잔고가 줄었다? 비용을 고려하며 마지막 관문을 완료하라"},"coin":null,"tool":"/funding-rates","cta":false},"hardware-wallet":{"slug":"hardware-wallet","cat":"wallets-security","en":"Hardware wallet","contentLocale":"ko","term":"하드웨어 지갑(Hardware Wallet)","aka":["하드월렛","하드웨어 월렛","hardware wallet"],"short":"하드웨어 지갑은 개인 키를 전용 보안 기기 안에 보관하고 거래 서명도 기기 안에서 처리해 키가 컴퓨터나 휴대폰에 노출되지 않게 하는 지갑입니다.","body":["레저(Ledger), 트레저(Trezor) 같은 제품이 잘 알려져 있습니다. 컴퓨터나 휴대폰 앱은 거래 내용을 만들어 기기로 보내기만 하고, 실제 서명은 기기 안에서 이뤄집니다. 사용자는 기기 화면에 표시된 주소와 금액을 확인한 뒤 버튼을 눌러 승인합니다.","이 구조 덕분에 컴퓨터가 악성코드에 감염돼도 키 자체를 빼 가기는 어렵습니다. 다만 기기 화면을 확인하지 않고 승인하면 공격자가 바꿔치기한 주소로 송금될 수 있습니다.",["기기를 잃어버려도 ",["시드 문구","seed-phrase"],"가 있으면 새 기기에서 복구할 수 있습니다. 반대로 시드 문구를 다른 사람이 알면 기기가 없어도 자산을 가져갈 수 있습니다. 구매는 제조사 공식 경로에서 하는 것이 기본입니다."]],"example":"하드웨어 지갑으로 0.8 ETH를 보내려고 컴퓨터 지갑 앱에 받는 주소를 붙여 넣었다고 가정합니다. 기기 화면에는 0x7a3f로 시작해 c91e로 끝나는 주소와 0.8 ETH가 표시됩니다. 원래 받을 주소의 앞 6자리와 끝 6자리를 직접 대조해 보고 일치할 때만 승인 버튼을 눌러야 합니다. 화면 주소가 다르다면 컴퓨터가 감염됐을 가능성이 있으니 즉시 취소합니다.","mistakes":["포장 안에 미리 적힌 시드 문구 카드가 들어 있는 기기를 그대로 사용합니다.","기기 화면의 주소와 금액을 확인하지 않고 습관적으로 승인 버튼을 누릅니다.","펌웨어 업데이트라며 시드 문구를 웹사이트에 입력하라는 안내를 따릅니다."],"faq":[{"q":"하드웨어 지갑을 잃어버리면 코인도 사라지나요?","a":"코인은 블록체인에 기록돼 있고 기기는 키를 보관할 뿐입니다. 시드 문구가 있으면 새 기기나 호환 지갑에서 복구할 수 있습니다."},{"q":"하드웨어 지갑은 어디서 사야 하나요?","a":"제조사 공식 사이트나 공식 판매처에서 새 제품을 사는 것이 안전합니다. 개봉된 제품이나 중고 기기는 조작 위험이 있어 피하는 것이 좋습니다."}],"title":"하드웨어 지갑이란? 원리와 안전한 사용법","description":"하드웨어 지갑의 작동 원리, 기기를 잃어버렸을 때의 복구 방법, 구매와 사용 시 꼭 확인할 점을 알려 드립니다.","related":[["cold-wallet","콜드월렛(Cold Wallet, 콜드 스토리지)","콜드월렛은 개인 키를 인터넷과 분리된 환경에 보관해 온라인 해킹 위험을 크게 줄인 암호화폐 보관 방식입니다."],["seed-phrase","시드 문구(Seed Phrase, 복구 문구)","시드 문구는 지갑을 만들 때 생성되는 12개 또는 24개의 영어 단어 목록으로, 이것만 있으면 지갑의 모든 개인 키와 자산을 복구할 수 있는 마스터 키입니다."],["private-key","개인 키(Private Key)","개인 키는 블록체인 주소의 자산을 사용할 수 있게 해 주는 비밀 숫자로, 이 키로 거래에 서명해야 송금이 이뤄집니다."],["address-poisoning","주소 오염 공격(Address Poisoning)","주소 오염 공격은 내 주소와 앞뒤 글자가 비슷한 가짜 주소로 소액이나 0원 거래를 보내 거래 내역에 섞어 두고, 다음 송금 때 그 주소를 잘못 복사하게 만드는 사기입니다."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"내 코인은 어디에 있을까: 거래소 vs 지갑"},"coin":null,"tool":null,"cta":false},"governance-token":{"slug":"governance-token","cat":"defi","en":"Governance token","contentLocale":"ko","term":"거버넌스 토큰(Governance Token)","aka":["거버넌스 코인","투표 토큰","governance token"],"short":"거버넌스 토큰은 보유량에 비례해 프로토콜이나 DAO의 주요 결정에 투표할 권리를 주는 토큰입니다.","body":[["유니스왑의 UNI, 에이브의 AAVE처럼 많은 ",["디파이","defi"]," 프로토콜이 거버넌스 토큰을 발행합니다. 보유자는 수수료 구조, 금고 자금 사용, 새 기능 도입 같은 제안에 투표하거나 직접 제안을 올릴 수 있습니다."],"투표권이 있다고 해서 주식처럼 이익 배당을 받는 것은 아닙니다. 수수료 분배 기능이 있는 토큰도 있지만, 투표권만 있는 경우가 많습니다. 그래서 거버넌스 토큰의 가치는 프로토콜의 미래 기대와 시장 수급에 크게 좌우됩니다.",[["에어드랍","airdrop"],"으로 배포되는 경우가 많고, 팀과 초기 투자자 물량에 베스팅 일정이 걸려 있기도 합니다. ",["토크노믹스","tokenomics"],"에서 ",["유통량","circulating-supply"],", 잠금 해제 일정, 상위 보유자 비중을 확인하면 투표권 집중도와 매도 압력을 가늠할 수 있습니다."]],"example":"총 공급량 1억 개인 거버넌스 토큰 G 가운데 2,000개를 보유했다고 가정합니다. 전체 공급 대비 투표권은 0.002%입니다. 그런데 실제 투표에는 공급량의 5%인 500만 개만 참여한다면, 내 2,000개는 그 안에서 0.04%의 비중이 됩니다. 반대로 한 초기 투자자가 300만 개를 갖고 있다면 혼자서 참여 투표의 60%를 차지해 결과를 좌우할 수 있습니다.","mistakes":["거버넌스 토큰을 보유하면 회사 주식처럼 배당을 받는다고 생각합니다.","잠금 해제 일정을 확인하지 않고 대량 물량 해제 직전에 삽니다.","투표권 위임을 하면 토큰 소유권까지 넘어간다고 오해합니다."],"faq":[{"q":"거버넌스 토큰으로 돈을 벌 수 있나요?","a":"토큰 자체는 투표권을 주는 것이 핵심이며 수익 분배는 프로토콜마다 다릅니다. 가격 변동이나 스테이킹 보상이 있을 수 있지만 보장된 수익은 아닙니다."},{"q":"투표권 위임은 안전한가요?","a":"위임은 보통 투표권만 넘기고 토큰은 내 지갑에 그대로 남습니다. 다만 위임 서명 화면을 가장한 피싱이 있으니 공식 사이트에서만 진행해야 합니다."}],"title":"거버넌스 토큰이란? 투표권과 가치 구조","description":"거버넌스 토큰의 뜻과 투표권이 작동하는 방식, 배당과의 차이, 유통량과 잠금 해제 일정을 확인하는 이유를 설명합니다.","related":[["dao","DAO(탈중앙화 자율 조직)","DAO(탈중앙화 자율 조직)는 경영진 대신 토큰 보유자의 투표와 스마트 컨트랙트 규칙으로 자금 사용과 주요 결정을 내리는 온라인 조직입니다."],["tokenomics","토크노믹스(Tokenomics)","토크노믹스는 토큰의 총발행량, 배분 비율, 언락 일정, 사용처, 소각과 인플레이션 규칙 등 토큰의 공급과 수요를 결정하는 경제 구조 전체를 말합니다."],["airdrop","에어드랍(Airdrop)","에어드랍은 프로젝트가 홍보, 커뮤니티 보상, 탈중앙화 분배를 위해 특정 조건을 만족한 지갑에 토큰을 무료로 나눠 주는 것입니다."],["coin-vs-token","코인과 토큰의 차이(Coin vs Token)","코인은 자체 블록체인의 기본 자산(예: BTC, ETH)이고, 토큰은 다른 블록체인 위에서 스마트 컨트랙트로 발행된 자산(예: 이더리움 위의 USDT)입니다."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"usdt":{"slug":"usdt","cat":"stablecoins","en":"USDT (Tether)","contentLocale":"ko","term":"USDT(테더)","aka":["테더","Tether","USDT"],"short":"USDT(테더)는 테더(Tether)사가 발행하는 미국 달러 연동 스테이블코인으로, 거래량과 시가총액 기준 가장 큰 스테이블코인입니다.","body":[["테더사는 발행한 USDT만큼 현금, 미국 단기 국채 등 준비자산을 보유한다고 밝히고 정기적으로 준비자산 보고서를 공개합니다. 해외 ",["거래소","centralized-exchange"],"의 많은 현물과 선물 마켓이 USDT를 기준 통화로 씁니다."],["USDT는 트론, ",["이더리움","ethereum"],", 솔라나, BNB 체인 등 여러 네트워크에서 발행됩니다. 같은 USDT라도 네트워크별로 수수료와 속도가 다르고, 받는 쪽과 네트워크가 일치해야 하므로 송금 전 확인이 필수입니다."],["국내에서는 원화로 USDT를 살 때 김치 프리미엄이 붙어 환율보다 비싸거나 싸게 거래되기도 합니다. 규제 환경도 지역마다 달라, 유럽에서는 ",["MiCA","mica"]," 시행 이후 일부 거래소가 역내 사용자의 USDT 거래를 제한했습니다."]],"example":"원·달러 환율이 1,350원인데 국내 원화 시장에서 USDT가 1,390원에 거래된다고 가정합니다. 프리미엄은 40원 나누기 1,350원으로 약 3%입니다. 이때 1,000만 원으로 USDT를 사면 약 7,194 USDT를 받는데, 환율 기준이라면 약 7,407 USDT를 받을 수 있었으므로 약 213 USDT만큼 비싸게 산 셈입니다. 프리미엄이 사라지면 같은 USDT를 다시 원화로 바꿀 때 그 차이가 손실로 확정됩니다.","mistakes":["USDT 원화 가격이 항상 환율과 같다고 생각합니다.","TRC-20 주소로 ERC-20 USDT를 보내는 등 네트워크를 혼동합니다.","USDT를 은행 예금처럼 원금이 보장되는 자산으로 여깁니다."],"faq":[{"q":"USDT는 정말 1달러인가요?","a":"1달러에 가깝게 유지되도록 설계됐고 대부분 그 근처에서 거래되지만, 시장 상황에 따라 약간 위아래로 움직일 수 있습니다. 1달러 상환은 테더사의 조건에 따른 것이며 개인이 직접 쓰기는 어렵습니다."},{"q":"USDT 송금은 어떤 네트워크가 좋나요?","a":"받는 쪽이 지원하는 네트워크 가운데 수수료와 속도가 적당한 것을 고르면 됩니다. 트론과 일부 레이어2는 수수료가 낮은 편이지만 거래소마다 지원 여부가 다릅니다."}],"title":"USDT(테더)란? 뜻과 김치 프리미엄·송금 팁","description":"USDT(테더)의 뜻과 준비자산 구조, 네트워크별 송금 차이, 원화로 살 때 김치 프리미엄이 생기는 이유를 설명합니다.","related":[["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다."],["usdc","USDC(USD 코인)","USDC는 미국 기업 서클(Circle)이 발행하는 미국 달러 연동 스테이블코인으로, 현금과 단기 미국 국채 등 준비자산으로 1대1 가치를 뒷받침합니다."],["blockchain-network","입금 네트워크(체인 선택)","입금 네트워크는 같은 코인을 어떤 블록체인으로 보낼지 고르는 설정으로, 보내는 쪽과 받는 쪽의 네트워크가 반드시 같아야 합니다."],["depeg","디페깅(Depeg)","디페깅은 1달러 같은 기준 가치에 고정(페깅)되도록 설계된 스테이블코인이나 자산의 가격이 그 기준에서 눈에 띄게 벗어나는 현상입니다."],["p2p-trading","P2P 거래(C2C)","P2P 거래는 거래소가 중개하는 게시판에서 개인끼리 은행 이체 등 법정화폐로 대금을 주고받고 USDT 같은 코인을 사고파는 방식입니다."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT는 달러일까요? 코인을 살 때 왜 항상 보일까요?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":true},"synthetic-dollar":{"slug":"synthetic-dollar","cat":"stablecoins","en":"Synthetic dollar (delta-neutral stablecoin)","contentLocale":"ko","term":"합성 달러(델타 중립 스테이블코인)","aka":["합성 달러","델타 중립 스테이블코인","Synthetic dollar"],"short":"합성 달러는 현물 암호화폐를 보유하면서 같은 규모의 선물 숏 포지션으로 가격 변동을 상쇄해 1달러 가치를 만드는 델타 중립형 스테이블코인입니다.","body":[["대표적인 예가 Ethena의 USDe입니다. 프로토콜은 ETH나 ",["BTC","bitcoin"]," 같은 자산을 보유하고, 동시에 ",["무기한 선물","perpetual-futures"]," 시장에서 같은 수량을 숏으로 잡습니다. 가격이 오르면 현물은 이익, 숏은 손실이 나고 내려가면 반대가 되어 전체 가치가 거의 변하지 않습니다. 이 상태를 델타 중립이라고 합니다."],["수익은 주로 ",["펀딩비","funding-rate"],"에서 나옵니다. 시장이 강세일 때는 롱 보유자가 숏 보유자에게 펀딩비를 내는 경우가 많아 숏을 잡은 프로토콜이 이를 받습니다. 여기에 ",["스테이킹","staking"]," 보상이 더해질 수도 있습니다. 반대로 펀딩비가 오래 마이너스로 유지되면 프로토콜이 비용을 내야 하므로 수익이 줄거나 준비 기금이 쓰입니다."],["은행 예금 대신 ",["거래소","centralized-exchange"]," 포지션과 커스터디에 의존하기 때문에 거래소 위험, 담보 자산의 ",["디페깅","depeg"],", 극단적 시장에서 헤지가 깨지는 위험이 있습니다. 준비금 기반 스테이블코인과 같은 성격으로 보면 안 됩니다."]],"example":"ETH가 2,000달러일 때 프로토콜이 10 ETH(20,000달러)를 보유하고 10 ETH 숏을 잡았다고 가정합니다. ETH가 1,600달러로 내리면 현물 가치는 16,000달러로 4,000달러 줄지만 숏 포지션에서 4,000달러 이익이 나서 합계는 20,000달러로 유지됩니다. 펀딩비가 8시간마다 0.01%라면 하루 세 번, 20,000달러 기준 회당 2달러, 하루 약 6달러를 받는 구조입니다. 실제 정산 주기는 거래소와 상품마다 다릅니다.","mistakes":["합성 달러의 수익률을 고정 이자로 착각합니다. 펀딩비에 따라 크게 달라집니다.","현물과 숏이 서로 상쇄되니 위험이 전혀 없다고 생각합니다.","펀딩비가 마이너스로 바뀌는 시기의 비용을 고려하지 않습니다."],"faq":[{"q":"합성 달러는 어디서 수익이 나나요?","a":"주로 숏 포지션이 받는 펀딩비와, 담보로 쓰는 스테이킹 자산의 보상에서 나옵니다. 시장 상황에 따라 수익률이 크게 변합니다."},{"q":"USDe는 USDT와 같은 스테이블코인인가요?","a":"아닙니다. USDT는 발행사의 준비금에 기반하고, USDe는 현물과 선물 헤지 포지션으로 가치를 유지합니다. 위험의 종류가 다릅니다."}],"title":"합성 달러란? 델타 중립 스테이블코인 USDe 원리","description":"합성 달러(델타 중립 스테이블코인)의 작동 방식, 펀딩비 수익 구조와 숨은 위험을 예시로 설명합니다.","related":[["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."],["hedging","헤지(Hedging)","헤지는 이미 가진 포지션의 가격 변동 위험을 줄이기 위해 반대 방향으로 움직이는 포지션을 함께 잡는 위험 관리 방법입니다."],["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다."],["depeg","디페깅(Depeg)","디페깅은 1달러 같은 기준 가치에 고정(페깅)되도록 설계된 스테이블코인이나 자산의 가격이 그 기준에서 눈에 띄게 벗어나는 현상입니다."]],"lesson":null,"coin":{"slug":"ethena-usde","name":"Ethena USDe","symbol":"USDE"},"tool":"/funding-rates","cta":false}});
